// Level number of get/setsockopt for local domain sockets
const SOL_LOCAL = 0

// Socket options.
const (
	LOCAL_PEERCRED = 1
	// retrieve peer pid
	LOCAL_PEERPID = 2
	// retrieve eff. peer pid
	LOCAL_PEEREPID = 3
	// retrieve peer UUID
	LOCAL_PEERUUID = 4
	// retrieve eff. peer UUID
	LOCAL_PEEREUUID = 5
	// retrieve peer audit token
	LOCAL_PEERTOKEN = 6
)

// [XSI] Definitions for UNIX IPC domain.
type SockaddrUn struct {
	SunLen    uint8
	SunFamily SaFamilyT
	SunPath   [104]c.Char
}

type Uint32T = c.Uint

// Compatibility sizes follow this platform's native sockaddr_storage.
const (
	ALIGNSIZE = unsafe.Alignof(SockaddrStorage{})
	MAXSIZE   = X_SS_MAXSIZE
	PAD1_SIZE = unsafe.Sizeof(SockaddrStorage{}.pad1)
	PAD2_SIZE = unsafe.Sizeof(SockaddrStorage{}.pad2)
)
